function clearFly(){timers.forEach(clearTimeout);timers=[];fly.innerHTML="";busy=false}
function later(ms,f){timers.push(setTimeout(f,ms))}
function runAcroGen(S,A,F,later,done){
  A.classList.add("hid");
  const box=S.getBoundingClientRect(),items=[];
  [...A.children].forEach((row,ri)=>{
    [row.querySelector("i"),...row.querySelectorAll(".rest>span")].forEach((c,ci)=>{
      const r=c.getBoundingClientRect(),cs=getComputedStyle(c),f=document.createElement("span");
      f.className="fch";f.textContent=c.textContent;
      Object.assign(f.style,{left:(r.left-box.left)+"px",top:(r.top-box.top)+"px",fontSize:cs.fontSize,fontWeight:cs.fontWeight,fontFamily:cs.fontFamily,color:cs.color});
      F.appendChild(f);items.push({f,ri,ci,x:r.left-box.left,y:r.top-box.top,w:r.width,h:r.height});
    });
  });
  const inis=items.filter(t=>t.ci===0),K=Math.min(2,(box.height*0.2)/inis[0].h);
  const gap=inis[0].w*K*0.9,total=inis.reduce((a,t)=>a+t.w*K,0)+gap*(inis.length-1);
  const restH=items.find(t=>t.ci>0).h,maxN=Math.max(...items.map(t=>t.ci)),KB=Math.min(1.5,(box.height*0.62-inis[0].h*K)/(restH*maxN));
  let x=box.width/2-total/2;const yA=Math.max(20,(box.height-(inis[0].h*K+6+maxN*restH*KB*0.92))/2);
  inis.forEach(t=>{t.ax=x;t.ay=yA;x+=t.w*K+gap});
  const tf=(dx,dy,k)=>`translate(${dx}px,${dy}px) scale(${k})`;
  items.forEach(t=>{
    const ini=inis[t.ri];
    if(t.ci===0){t.pre=tf(ini.ax-t.x,ini.ay-t.y,K*0.85);t.A=tf(ini.ax-t.x,ini.ay-t.y,K)}
    else{
      const cw=t.w*KB/1.42,cx=ini.ax+ini.w*K/2-cw/2,cy=ini.ay+ini.h*K+6+(t.ci-1)*t.h*KB*0.92;
      t.A=tf(cx-t.x,cy-t.y,KB);t.pre=tf(cx-t.x,ini.ay+ini.h*K*0.4-t.y,KB);
    }
    t.f.style.transition="none";t.f.style.opacity=0;t.f.style.transform=t.pre;
  });
  void F.offsetWidth;
  /* mismo ritmo que la línea del tiempo del slide 1: 1.3 s con curva ease y una pausa de 0.5 s antes de mover */
  const T1=1300,DROP=T1,MORPH=DROP+1300+360+150;
  later(30,()=>inis.forEach(t=>{t.f.style.transition="transform 1.3s ease,opacity 1.3s ease";t.f.style.opacity=1;t.f.style.transform=t.A}));
  later(DROP,()=>items.filter(t=>t.ci>0).forEach(t=>{const d=(t.ci-1)*0.06+t.ri*0.05;
    t.f.style.transition=`transform 1.3s ease ${d}s,opacity 1.3s ease ${d}s`;t.f.style.opacity=1;t.f.style.transform=t.A}));
  later(MORPH,()=>items.forEach(t=>{const d=0.5+t.ri*0.09+t.ci*0.015;
    t.f.style.transition=`transform 1.4s ease ${d}s`;t.f.style.transform="none"}));
  later(MORPH+500+1400+330,()=>{A.classList.remove("hid");F.innerHTML="";done&&done()});
}
