const GRAD=["linear-gradient(150deg,#D9534F,#7A1F3D 60%,#F2B544 140%)","linear-gradient(150deg,#5B8DB8,#1B3A5C 60%,#F4EBDD 150%)","linear-gradient(150deg,#1F9E9A,#0E5A7A 60%,#F2B544 130%)","linear-gradient(150deg,#4B5878,#22283D 65%,#E8775A 140%)","linear-gradient(150deg,#2BB3C9,#13607F 60%,#F4EBDD 150%)","linear-gradient(150deg,#E8A25A,#B4533A 55%,#163A49 130%)"];
const dWrap=document.getElementById("dests"),sheet=document.getElementById("sheet");
function buildDests(){dWrap.innerHTML="";
DST[L].forEach((d,gi)=>{
  d.g=GRAD[gi];
  const b=document.createElement("button");
  b.className="dest";b.style.background=d.g;
  b.innerHTML=`<small>${d.s}</small><h3>${d.n}</h3>`;
  b.onclick=()=>{
    document.getElementById("d-hero").style.background=d.g;
    document.getElementById("d-name").textContent=d.n;
    document.getElementById("d-text").textContent=d.t;
    document.getElementById("d-tag").textContent=d.real?(L==="es"?"Historia real de un socio":"A real member story"):(L==="es"?"Ejemplo, con datos por definir":"Example, details to be confirmed");
    document.getElementById("d-facts").innerHTML=d.f.map(([a,v])=>`<div class="fact"><small>${a}</small><b>${v}</b></div>`).join("");
    sheet.hidden=false;document.getElementById("d-close").focus();
  };
  dWrap.appendChild(b);
});}
buildDests();
document.getElementById("d-close").onclick=()=>sheet.hidden=true;
sheet.onclick=e=>{if(e.target===sheet)sheet.hidden=true};

/* Proyección */
const fmt=n=>"$"+Math.round(n).toLocaleString("en-US")+" USD";
const gasto=document.getElementById("gasto"),anios=document.getElementById("anios"),infl=document.getElementById("infl");
function calc(){
  const A=Number(gasto.value.replace(/[^\d]/g,""))||0,n=+anios.value,i=+infl.value/100;
  let total=0,vals=[];
  for(let k=0;k<n;k++){const v=A*Math.pow(1+i,k);vals.push(v);total+=v}
  document.getElementById("o-anios").textContent=n+(L==="es"?" años":" years");
  document.getElementById("o-infl").textContent=infl.value+"%";
  document.getElementById("r-lead").textContent=L==="es"?`En ${n} años se van a gastar, sin dejarles ningún patrimonio`:`In ${n} years you will spend, with nothing to show for it`;
  document.getElementById("r-total").textContent=fmt(total);
  document.getElementById("r-plano").textContent=fmt(A*n);
  document.getElementById("r-ultimo").textContent=fmt(vals[n-1]||0);
  document.getElementById("r-axis").textContent=(L==="es"?"Año ":"Year ")+n;
  const max=Math.max(...vals,1);
  document.getElementById("bars").innerHTML=vals.map((v,k)=>`<div class="bar${k===n-1?" last":""}" style="height:${v/max*100}%"></div>`).join("");
}
gasto.addEventListener("input",()=>{const d=gasto.value.replace(/[^\d]/g,"");gasto.value=d?Number(d).toLocaleString("en-US"):"";calc()});
anios.oninput=calc;infl.oninput=calc;calc();

/* Idioma */
const ACRO={es:[["C","réditos"],["R","oyal"],["H","oliday"]],en:[["R","oyal"],["H","oliday"],["C","redits"]]};

/* Vacaciones: preguntas → lo gastado → lo que van a gastar con inflación */
const s5=document.getElementById("s5v"),vbig=document.getElementById("vbig"),vtext=document.getElementById("vtext"),vopts=document.getElementById("vopts"),vqw=document.getElementById("vqw"),vimg=document.getElementById("vimg"),vtl=document.getElementById("vtl");
const VQS=[1,2,3,4,6].map(n=>document.getElementById("vq"+n));
const VIN={years:document.getElementById("vyears"),cost:document.getElementById("vcost"),per:document.getElementById("vper"),past:document.getElementById("vpast"),inf:document.getElementById("vinf")};
let vT=[],vst=-1,vstep=0;const laterV=(ms,f)=>vT.push(setTimeout(f,ms));
const vnum=el=>parseFloat((el.value||"").replace(/,/g,""))||0;
const money=v=>"$"+Math.round(v).toLocaleString("en-US");
function vShowBig(key,done){
  const left=vimg.classList.contains("on");vbig.classList.toggle("left",left);
  const shown=VQS.some(q=>q.classList.contains("show"));
  vbig.style.top=shown?(vqw.getBoundingClientRect().bottom-s5.getBoundingClientRect().top+20)+"px":"0px";
  vtext.style.transition="none";vtext.style.transform="";vtext.style.opacity=0;vtext.textContent=T[L][key];vbig.classList.add("on");void vtext.offsetWidth;
  vtext.style.transform="scale(.94)";void vtext.offsetWidth;
  vtext.style.transition="opacity .5s ease,transform .6s cubic-bezier(.3,1.2,.5,1)";vtext.style.opacity=1;vtext.style.transform="none";
  laterV(600,done||(()=>{}));
}
function vMorph(q,done){
  const s=q.querySelector(".vq-s");q.classList.add("show");
  const tr=s.getBoundingClientRect(),br=vtext.getBoundingClientRect();
  const k=parseFloat(getComputedStyle(s).fontSize)/parseFloat(getComputedStyle(vtext).fontSize);
  vtext.style.transformOrigin="0 0";vtext.style.transition="transform .85s cubic-bezier(.6,0,.25,1),opacity .45s ease .4s";
  vtext.style.transform=`translate(${tr.left-br.left}px,${tr.top-br.top}px) scale(${k})`;vtext.style.opacity=0;
  laterV(450,()=>q.classList.add("in"));
  laterV(880,()=>{vbig.classList.remove("on");vopts.classList.remove("res");vtext.style.transition="none";vtext.style.transform="";vtext.style.transformOrigin="";q.classList.add("ans");done&&done()});
}
function vCalc(){
  const N=Math.max(1,Math.min(60,Math.round(vnum(VIN.years))||20)),annual=vnum(VIN.cost)*(vnum(VIN.per)||1),r=vnum(VIN.inf)/100,pastY=vnum(VIN.past);
  let tot=0;const vals=[];for(let t=0;t<N;t++){const v=annual*Math.pow(1+r,t);vals.push(v);tot+=v}
  return {N,annual,r,pastY,past:annual*pastY,base:annual*N,tot,infl:tot-annual*N,vals};
}
const VNOW=new Date().getFullYear();
function vLayout(){
  const c=vCalc(),P=Math.max(c.pastY,0),pf=Math.max(P,c.N*0.28),ff=c.N;
  vtl.style.setProperty("--pf",pf+"fr");vtl.style.setProperty("--ff",ff+"fr");
  document.getElementById("vpY").textContent=P+" "+T[L].v_yrs;document.getElementById("vfutY").textContent=c.N+" "+T[L].v_yrs;
  document.getElementById("vyA").textContent=VNOW-P;document.getElementById("vyB").textContent=VNOW;document.getElementById("vyC").textContent=VNOW+c.N;
  {const per=Math.max(1,Math.round(vnum(VIN.per))||1);document.getElementById("vPalms").innerHTML=VIC.repeat(Math.min(per,6));document.getElementById("vPerTxt").textContent=per+" "+(per===1?T[L].v_pv1:T[L].v_pvn);document.getElementById("vMidN").textContent=c.N;document.getElementById("vNowY2").textContent=VNOW;document.getElementById("vEndY").textContent=VNOW+c.N;}
  const ax=vtl.querySelector(".vtl-axis");ax.style.setProperty("--nowx",ax.querySelector(".ax-p").getBoundingClientRect().width+"px");
  return c;
}
function vBars(anim){
  const c=vLayout(),mx=Math.max(...c.vals,1),P=Math.round(c.pastY),bp=document.getElementById("vtlP"),bf=document.getElementById("vtlF");
  if(bp.children.length!==P||bf.children.length!==c.N){bp.innerHTML='<div class="vb vb-p"><i class="vb-b"></i></div>'.repeat(P);bf.innerHTML='<div class="vb"><i class="vb-i"></i><i class="vb-b"></i></div>'.repeat(c.N);if(vstep>=13)anim=true}
  [...bp.children].forEach(b=>b.querySelector(".vb-b").style.height=(c.annual/mx*100)+"%");
  [...bf.children].forEach((b,t)=>{b.querySelector(".vb-b").style.height=(c.annual/mx*100)+"%";b.querySelector(".vb-i").style.height=((c.vals[t]-c.annual)/mx*100)+"%"});
  if(anim){const all=[...bp.children,...bf.children];all.forEach((b,k)=>{b.classList.remove("in");laterV(80+k*(1800/all.length),()=>b.classList.add("in"))})}
}
function vUpdate(){
  const c=vLayout();
  if(vstep>=12){document.getElementById("vpastN").textContent=money(c.past);document.getElementById("vfutN").textContent=money(c.tot);document.getElementById("vd1").textContent=money(vnum(VIN.cost));document.getElementById("vd3").textContent=c.pastY;document.getElementById("vd4").textContent=c.N;document.getElementById("vd5").textContent=money(vnum(VIN.cost)*Math.pow(1+c.r,c.N))}
  if(vstep>=13){vBars(false);document.getElementById("vt0").textContent=money(c.base);document.getElementById("vt1").textContent=money(c.infl)}
  if(vstep>=14){document.getElementById("vmA").textContent=money(c.annual);document.getElementById("vmR").textContent=money(c.annual/12)}
}
const VSTEPS=[
  /*0 Q1 → lista + SÍ + foto*/ ()=>{vMorph(VQS[0],()=>laterV(400,()=>vimg.classList.add("on")));return 2000},
  /*1 Q2 + opciones*/          ()=>{vopts.classList.add("res");vShowBig("vq2");laterV(500,()=>vopts.classList.add("on"));return 1700},
  /*2 Q2 → lista*/             ()=>{vopts.classList.remove("on");laterV(350,()=>vMorph(VQS[1]));return 1300},
  /*2 Q3 → lista*/             ()=>{vShowBig("vq3");laterV(1700,()=>vMorph(VQS[2]));return 2700},
  /*3 Q4 → lista*/             ()=>{vShowBig("vq4");laterV(1700,()=>vMorph(VQS[3]));return 2700},
  /*4 foto chica + Q6 → lista*/()=>{vimg.classList.add("small");laterV(500,()=>vShowBig("vq6",()=>laterV(1100,()=>{const sp=document.getElementById("vqsep");sp.classList.add("show");void sp.offsetWidth;sp.classList.add("in");vMorph(VQS[4])})));return 3200},
  /*5 totales en línea del tiempo*/ ()=>{vimg.classList.add("gone");vqw.classList.add("out");vstep=12;vLayout();const a=document.getElementById("vpastN"),b=document.getElementById("vfutN");a.textContent=b.textContent="$0";
      laterV(700,()=>{vtl.classList.add("von","vtop")});
      laterV(1100,()=>vtl.classList.add("vax"));
      laterV(1500,()=>countTo(a,vCalc().past,1500,0));
      laterV(2700,()=>{vtl.classList.add("vnow")});
      laterV(3300,()=>countTo(b,vCalc().tot,1800,0));
      return 5300},
  /*6 análisis: barras + desglose*/ ()=>{vstep=13;vBars(true);vtl.classList.add("vbars");const c=vCalc();
      laterV(2200,()=>{vtl.classList.add("van");const e0=document.getElementById("vt0"),e1=document.getElementById("vt1");e0.textContent=e1.textContent="$0";laterV(300,()=>countTo(e0,c.base,1300,0));laterV(1200,()=>countTo(e1,c.infl,1300,0))});
      return 4800},
  /*7 al mes*/ ()=>{vstep=14;const c=vCalc(),a=document.getElementById("vmA"),r=document.getElementById("vmR");a.textContent=money(c.annual);r.textContent="$0";vtl.classList.add("vmes1");laterV(1400,()=>countTo(r,c.annual/12,1400,0));laterV(3000,()=>vtl.classList.add("vmes2"));return 3600}
];
let vInfT=0;
function vRun(k){vst=-1;clearTimeout(vInfT);const d=VSTEPS[k]();vstep=Math.max(vstep,k+1);laterV(d,()=>{vst=k+1;if(k+1===7)vMaybeAuto()})}
function vMaybeAuto(){if(vst!==7||!VIN.inf.value)return;clearTimeout(vInfT);vInfT=setTimeout(()=>{if(vst===7&&VIN.inf.value)vRun(7)},1100)}
function vReset(){clearTimeout(vInfT);vT.forEach(clearTimeout);vT=[];vst=-1;vstep=0;vbig.classList.remove("on","left");vbig.style.top="0px";vopts.classList.remove("on","res");VQS.forEach(q=>q.classList.remove("show","in","ans"));document.getElementById("vqsep").classList.remove("show","in");Object.values(VIN).forEach(i=>i.value="");vimg.classList.remove("on","small","gone");vqw.classList.remove("out");vtl.classList.remove("von","vtop","vax","vnow","vbars","van","vmes1","vmes2");document.getElementById("vtlP").innerHTML=document.getElementById("vtlF").innerHTML="";vtext.style.opacity=0;
  laterV(500,()=>vShowBig("vq1",()=>{vst=0}))}
s5.addEventListener("click",()=>{
  if(vst===VSTEPS.length){go(5);return}if(vst<0||vst>=VSTEPS.length)return;vRun(vst);
});
s5.querySelectorAll("[data-t]").forEach(el=>el.textContent=T[L][el.dataset.t]);
s5.querySelectorAll(".vq-in").forEach(l=>l.addEventListener("click",e=>e.stopPropagation()));
Object.values(VIN).forEach(el=>el.addEventListener("focus",()=>{const st=document.querySelector(".stage");const z=()=>{s5.scrollLeft=0;s5.scrollTop=0;st.scrollLeft=0;st.scrollTop=0};z();requestAnimationFrame(z);setTimeout(z,300)}));
[VIN.years,VIN.per,VIN.past].forEach(el=>el.addEventListener("input",()=>{el.value=el.value.replace(/\D/g,"").slice(0,2);vUpdate()}));
VIN.cost.addEventListener("input",()=>{const d=VIN.cost.value.replace(/\D/g,"").slice(0,7);VIN.cost.value=d?(+d).toLocaleString("en-US"):"";vUpdate()});
VIN.inf.addEventListener("input",()=>{VIN.inf.value=VIN.inf.value.replace(/[^\d.]/g,"").replace(/(\..*)\./g,"$1").slice(0,4);vUpdate();vMaybeAuto()});

