const TDX={orlando:{es:{place:"Orlando, Florida",hotel:"Club Wyndham Bonnet Creek",unit:"Villa 1 recámara · 7 noches · junto a Disney",cap:"2 adultos + 2 niños"},en:{place:"Orlando, Florida",hotel:"Club Wyndham Bonnet Creek",unit:"1-bedroom villa · 7 nights · next to Disney",cap:"2 adults + 2 kids"},ppl:[2,2],pub:1800,soc:399,room:"/presentacion/img/34.jpg",img:"/presentacion/img/35.jpg"}};
const tdx=document.getElementById("tdx");let tdxT=[];
function tdxOpen(card){
  const k=card.dataset.k,d=TDX[k];if(!d)return;tdxT.forEach(clearTimeout);tdxT=[];
  const t=d[L]||d.es;document.getElementById("tdxPlace").textContent=t.place;document.getElementById("tdxHotel").textContent=t.hotel;document.getElementById("tdxUnit").textContent=t.unit;document.getElementById("tdxCap").innerHTML=d.ppl?`<span class="cm-ppl">${PSVG.repeat(d.ppl[0])}${KSVG.repeat(d.ppl[1])}</span><small>${t.cap}</small>`:"";
  document.getElementById("tdxA").src=d.img||card.querySelector("img").src;const rb=document.getElementById("tdxB");rb.style.backgroundImage=d.room?`url(${d.room})`:"";rb.classList.toggle("has",!!d.room);
  tdx.querySelectorAll("[data-t]").forEach(el=>el.textContent=T[L][el.dataset.t]);document.getElementById("tdxCrh").textContent=L==="es"?"CRH":"RHC";
  const pub=document.getElementById("tdxPub"),soc=document.getElementById("tdxSoc"),sav=document.getElementById("tdxSave");pub.textContent=soc.textContent=sav.textContent="$0";
  tdx.querySelector(".r0 i").style.width="0";tdx.querySelector(".r1 i").style.width="0";
  tdx.className="tdx";void tdx.offsetWidth;tdx.classList.add("on");
  tdxT.push(setTimeout(()=>tdx.classList.add("s1"),500));
  tdxT.push(setTimeout(()=>{tdx.classList.add("s2");tdx.querySelector(".r0 i").style.width="100%";countTo(pub,d.pub,1400,0)},1500));
  tdxT.push(setTimeout(()=>{tdx.classList.add("s3");tdx.querySelector(".r1 i").style.width=(d.soc/d.pub*100)+"%";countTo(soc,d.soc,1000,0)},3000));
  tdxT.push(setTimeout(()=>{tdx.classList.add("s4");countTo(sav,d.pub-d.soc,1400,0)},4400));
}
