/* T-P: comparativa en T con los datos del cliente */
const stp=document.getElementById("stp"),tpT=document.getElementById("tptitle"),tpBox=document.getElementById("tp");let tpTm=[],tpst=-1;
const TPROWS=[...tpBox.querySelectorAll(".tp-row")];
function tpFill(){
  const c=vCalc(),t=T[L],cost=vnum(VIN.cost),per=vnum(VIN.per)||1,N=c.N,set=(id,v)=>{document.getElementById(id).textContent=v};
  const lab=[t.tp_s1,t.tp_s2,t.tp_s3.replace("{n}",N),t.tp_s4.replace("{y}",VNOW+N),t.tp_s5,t.tp_s6];
  lab.forEach((l,k)=>{set("tpL"+(k+1)+"s",l);set("tpR"+(k+1)+"s",l)});
  set("tpL1",per);set("tpR1",t.tp_r1);
  set("tpL2",money(cost));set("tpR2","$727.50");
  set("tpL3",money(c.tot));set("tpR3",t.tp_r3);
  set("tpL4",money(cost*Math.pow(1+c.r,N)));set("tpR4",t.tp_r4);
  set("tpL5",t.tp_l5);set("tpR5",t.tp_r5);
  set("tpL6",t.tp_l6);set("tpR6",t.tp_r6);
  const sub=(id,txt)=>{const b=document.getElementById(id);let e=b.nextElementSibling;if(!e||!e.classList.contains("tp-sub")){e=document.createElement("em");e.className="tp-sub";b.after(e)}e.textContent=txt};
  sub("tpL2",money(cost*per/12)+" "+t.tp_mo);sub("tpL3",t.tp_l3x);sub("tpR1",t.tp_r1b);sub("tpR2",t.tp_r2b);sub("tpR3",t.tp_r3b);sub("tpR4",t.tp_r4b);sub("tpR5",t.tp_r5b);sub("tpR6",t.tp_r6b);
}
function tpReset(){tpTm.forEach(clearTimeout);tpTm=[];tpst=-1;tpBox.classList.remove("on");TPROWS.forEach(r=>r.classList.remove("l","r"));tpBox.querySelectorAll("[data-t]").forEach(el=>el.textContent=T[L][el.dataset.t]);tpFill();
  requestAnimationFrame(()=>{centerEl(tpT,stp);tpTm.push(setTimeout(()=>{tpT.style.transform="none"},1500));tpTm.push(setTimeout(()=>tpBox.classList.add("on"),2600));tpTm.push(setTimeout(()=>{tpst=0},3800))})}
stp.addEventListener("click",()=>{
  if(tpst<0)return;if(tpst>=TPROWS.length){go(6);return}
  const k=tpst;tpst=-1;tpFill();const r=TPROWS[k];r.classList.add("l");tpTm.push(setTimeout(()=>r.classList.add("r"),1000));tpTm.push(setTimeout(()=>{tpst=k+1},1700));
});
function setLang(l){/*presentacion-lang-img*/document.querySelectorAll("img.ph-en[data-src]").forEach((img)=>{if(l==="en"&&!img.getAttribute("src"))img.src=img.dataset.src;});
  L=l;
  [...document.querySelectorAll(".acro2>div")].forEach((d,k)=>{d.querySelector("i").textContent=ACRO[l][k%3][0];d.querySelector(".rest").innerHTML=[...ACRO[l][k%3][1].toUpperCase()].map(c=>"<span>"+c+"</span>").join("")});document.documentElement.lang=l;
  document.querySelectorAll("[data-t]").forEach(el=>el.textContent=T[l][el.dataset.t]);
  [...nav.children].forEach((b,k)=>b.querySelector("span").textContent=SEC[l][k]);
  document.getElementById("lang-es").classList.toggle("on",l==="es");document.getElementById("lang-en").classList.toggle("on",l==="en");
  buildDests();calc();
  VIS.clear();go(1);
}
